//! Localized non-Gregorian calendar data (month names, era names, patterns).
//!
//! The table is generated by tools/unicode/format/generate_calendars.py from
//! CLDR 48 and stores fully resolved names for the supported calendars.

const std = @import("std");
const dates_data = @import("dates_data.zig");

const blob = @embedFile("calendars_data.bin");

const header_len = 36;
const locale_count = readU16(8);
const record_count = readU16(10);
const locale_calendar_count = readU16(12);
const month_count = readU32(16);
const era_count = readU32(20);
const string_length = readU32(24);

const locale_offset = header_len;
const locale_calendar_offset = locale_offset + locale_count * 12;
const record_offset = locale_calendar_offset + locale_calendar_count * 4;
const month_offset = record_offset + record_count * 32;
const era_offset = month_offset + month_count * 12;
const strings_offset = era_offset + era_count * 16;

const flag_gregorian_months = 1;
const flag_leap_months = 2;

comptime {
    if (blob.len < header_len or !std.mem.eql(u8, blob[0..4], "CJKD") or
        blob[4] != 1)
    {
        @compileError("invalid calendar data");
    }
    if (strings_offset + @as(usize, string_length) != blob.len) {
        @compileError("invalid calendar data lengths");
    }
}

pub const Width = enum { wide, abbreviated, narrow };

pub const Style = enum { full, long, medium, short };

pub const MonthTable = struct {
    wide: [13][]const u8,
    abbreviated: [13][]const u8,
    narrow: [13][]const u8,
};

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, blob[offset..][0..4], .little);
}

fn strAt(offset: u32) []const u8 {
    if (offset == 0) return "";
    return std.mem.sliceTo(blob[strings_offset + @as(usize, offset) ..], 0);
}

const LocaleRecord = struct {
    id: []const u8,
    calendar_start: u16,
    calendar_count: u16,
};

fn localeAt(index: usize) LocaleRecord {
    const base = locale_offset + index * 12;
    const id_offset = readU32(base);
    const id_length = blob[base + 4];
    return .{
        .id = blob[strings_offset + @as(usize, id_offset) ..][0..id_length],
        .calendar_start = readU16(base + 6),
        .calendar_count = readU16(base + 8),
    };
}

fn lookupLocale(name: []const u8) ?LocaleRecord {
    var low: usize = 0;
    var high: usize = locale_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const record = localeAt(middle);
        switch (std.mem.order(u8, record.id, name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return record,
        }
    }
    return null;
}

fn findLocale(name: []const u8) ?LocaleRecord {
    if (lookupLocale(name)) |record| return record;
    if (std.mem.indexOfAny(u8, name, "-_")) |position| {
        if (lookupLocale(name[0..position])) |record| return record;
    }
    return lookupLocale("en");
}

const Record = struct {
    calendar: u8,
    flags: u8,
    month_count: u8,
    leap_month_count: u8,
    month_start: u32,
    era_start: u32,
    era_count: u16,
    leap_month_start: u16,
    patterns: [4]u32,
};

fn recordAt(index: usize) Record {
    const base = record_offset + index * 32;
    return .{
        .calendar = blob[base],
        .flags = blob[base + 1],
        .month_count = blob[base + 2],
        .leap_month_count = blob[base + 3],
        .month_start = readU32(base + 4),
        .era_start = readU32(base + 8),
        .era_count = readU16(base + 12),
        .leap_month_start = readU16(base + 14),
        .patterns = .{
            readU32(base + 16),
            readU32(base + 20),
            readU32(base + 24),
            readU32(base + 28),
        },
    };
}

fn findRecord(locale_name: []const u8, calendar: u8) ?Record {
    const locale = findLocale(locale_name) orelse return null;
    var low: usize = locale.calendar_start;
    var high: usize = locale.calendar_start + locale.calendar_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const base = locale_calendar_offset + middle * 4;
        const value = blob[base];
        if (value < calendar) {
            low = middle + 1;
        } else if (value > calendar) {
            high = middle;
        } else {
            return recordAt(readU16(base + 2));
        }
    }
    return null;
}

fn gregorianLocale(name: []const u8) ?dates_data.Locale {
    for (dates_data.locales) |locale| {
        if (std.mem.eql(u8, locale.id, name)) return locale;
    }
    if (std.mem.indexOfAny(u8, name, "-_")) |position| {
        for (dates_data.locales) |locale| {
            if (std.mem.eql(u8, locale.id, name[0..position])) return locale;
        }
    }
    return null;
}

/// Resolved month names for a calendar. Calendars that share the Gregorian
/// month names use the locale's Gregorian month data.
pub fn monthTable(
    locale_name: []const u8,
    calendar: u8,
    leap_year: bool,
) MonthTable {
    var table = MonthTable{
        .wide = [_][]const u8{""} ** 13,
        .abbreviated = [_][]const u8{""} ** 13,
        .narrow = [_][]const u8{""} ** 13,
    };
    const record = findRecord(locale_name, calendar) orelse return table;
    if (record.flags & flag_gregorian_months != 0) {
        const locale = gregorianLocale(locale_name) orelse
            gregorianLocale("en").?;
        for (0..12) |index| {
            table.wide[index] = locale.months_wide[index];
            table.abbreviated[index] = locale.months_abbreviated[index];
            table.narrow[index] = locale.months_narrow[index];
        }
        return table;
    }
    const use_leap = leap_year and record.leap_month_count != 0;
    const count: usize = if (use_leap)
        record.leap_month_count
    else
        record.month_count;
    const start: usize = if (use_leap)
        record.leap_month_start
    else
        record.month_start;
    var index: usize = 0;
    while (index < count) : (index += 1) {
        const base = month_offset + (start + index) * 12;
        table.wide[index] = strAt(readU32(base));
        table.abbreviated[index] = strAt(readU32(base + 4));
        table.narrow[index] = strAt(readU32(base + 8));
    }
    return table;
}

/// Localized era name for an era type; empty when the calendar has none.
pub fn eraName(
    locale_name: []const u8,
    calendar: u8,
    era_type: u16,
    width: Width,
) []const u8 {
    const record = findRecord(locale_name, calendar) orelse return "";
    var low: usize = 0;
    var high: usize = record.era_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const base = era_offset + (record.era_start + middle) * 16;
        const value = readU16(base);
        if (value < era_type) {
            low = middle + 1;
        } else if (value > era_type) {
            high = middle;
        } else {
            const offset: u32 = switch (width) {
                .wide => readU32(base + 4),
                .abbreviated => readU32(base + 8),
                .narrow => readU32(base + 12),
            };
            return strAt(offset);
        }
    }
    return "";
}

/// Resolved date pattern for a style, or null when the locale has none.
pub fn pattern(
    locale_name: []const u8,
    calendar: u8,
    style: Style,
) ?[]const u8 {
    const record = findRecord(locale_name, calendar) orelse return null;
    const value = switch (style) {
        .full => record.patterns[0],
        .long => record.patterns[1],
        .medium => record.patterns[2],
        .short => record.patterns[3],
    };
    if (value == 0) return null;
    return strAt(value);
}

test "calendar data" {
    const testing = @import("std").testing;
    const islamic_months = monthTable("en", 4, false);
    try testing.expectEqualStrings("Muharram", islamic_months.wide[0]);
    try testing.expectEqualStrings("Rajab", islamic_months.wide[6]);
    try testing.expectEqualStrings("Ramadan", islamic_months.wide[8]);
    const buddhist_months = monthTable("en", 1, false);
    try testing.expectEqualStrings("January", buddhist_months.wide[0]);
    try testing.expectEqualStrings("BE", eraName("en", 1, 0, .abbreviated));
    try testing.expectEqualStrings("Reiwa", eraName("en", 2, 236, .abbreviated));
    try testing.expectEqualStrings("Anno Hegirae", eraName("en", 4, 0, .wide));
    const full_pattern = pattern("en", 1, .full).?;
    try testing.expectEqualStrings("EEEE, MMMM d, y G", full_pattern);
    try testing.expectEqualStrings(
        "GGGGy年M月d日EEEE",
        pattern("ja", 1, .full).?,
    );
}
